        -----------------------------------------------------------------------------------------------------------------------------------
        -- EPST, LPST UPDATE
        -----------------------------------------------------------------------------------------------------------------------------------

        BEGIN
        
          SET @v_table_name = 'TH_BUF_OUT_WORK_ORDER_SPL'

          UPDATE TH_BUF_OUT_ORDER_TRACKING
          SET    TH_BUF_OUT_ORDER_TRACKING.EPST = B.EPST
               , TH_BUF_OUT_ORDER_TRACKING.LPST = B.LPST
          FROM   TH_BUF_OUT_ORDER_TRACKING A,
                 (
                    SELECT DEMAND_ID, SITE_ID, ROUTE_ID, OPERATION_ID, OUT_ITEM_ID, EPST, LPST
                    FROM   TH_OUT_ORDER_TRACKING
                    WHERE  MASTER_ID      = @v_master_id
                    AND    PLAN_ID        = @v_plan_id
                    AND    OUT_VERSION_ID = @v_plan_id+'BACK' -- ## 백업 기준..!!
                    AND    EPST           IS NOT NULL
                    GROUP BY DEMAND_ID,SITE_ID,ROUTE_ID,OPERATION_ID,OUT_ITEM_ID,EPST,LPST        
                 ) B
          WHERE  A.MASTER_ID      = @v_master_id
          AND    A.PLAN_ID        = @v_plan_id
          AND    A.OUT_VERSION_ID = @v_plan_id
          AND    A.DEMAND_ID      = B.DEMAND_ID
          AND    A.SITE_ID        = B.SITE_ID
          AND    A.ROUTE_ID       = B.ROUTE_ID
          AND    A.OPERATION_ID   = B.OPERATION_ID
          AND    A.OUT_ITEM_ID    = B.OUT_ITEM_ID          

          --LOG 생성
          SET @v_message = @@ROWCOUNT
          SET @n_log_count = @n_log_count + 1
          SET @sysdate = GETDATE()
          EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_WORK_ORDER_SPL', 'DELETE', @n_log_count, null, @v_message, null

          
          delete from th_out_order_tracking_back
          where  master_id = @v_master_id
          and    plan_id = @v_plan_id

          --LOG 생성
          SET @v_message = @@ROWCOUNT
          SET @n_log_count = @n_log_count + 1
          SET @sysdate = GETDATE()
          EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'th_out_order_tracking_back', 'DELETE', @n_log_count, null, @v_message, null

          insert into th_out_order_tracking_back
          select *
          from   th_out_order_tracking
          where  master_id = @v_master_id
          and    plan_id = @v_plan_id
          and    out_version_id = @v_plan_id+'BACK'   
          
          --LOG 생성
          SET @v_message = @@ROWCOUNT
          SET @n_log_count = @n_log_count + 1
          SET @sysdate = GETDATE()
          EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'th_out_order_tracking_back', 'INSERT', @n_log_count, null, @v_message, null

          -- ## 첫번째 결과 백업 삭제 - Order Tracking..!!
          delete from th_out_order_tracking
          where  master_id = @v_master_id
          and    plan_id = @v_plan_id
          and    out_version_id = @v_plan_id+'BACK'   

        END
        
        -----------------------------------------------------------------------------------------------------------------------------------
        -- 소수점 수량 몰아주기
        -----------------------------------------------------------------------------------------------------------------------------------
        
        BEGIN
          
          DECLARE C_OUT_ADJ CURSOR FOR
            SELECT A.ORG_WORK_ORDER_ID, A.WORK_ORDER_ID, A.WO_SEQ,
                   A.TOT_MOD_COMPLETE_QTY, A.TOT_MOD_OPERATION_QTY,
                   A.MOD_COMPLETE_QTY, A.MOD_OPERATION_QTY
            FROM   
                   (
                    SELECT A.ORG_WORK_ORDER_ID, A.WORK_ORDER_ID, A.START_TIME, A.END_TIME, A.COMPLETE_QTY, A.OPERATION_QTY, 
                           A.MOD_COMPLETE_QTY, A.MOD_OPERATION_QTY, A.WO_CNT, A.WO_SEQ,
                           SUM(CASE WHEN A.WO_SEQ = 1 THEN 0 ELSE A.MOD_COMPLETE_QTY END) OVER (PARTITION BY A.ORG_WORK_ORDER_ID) AS TOT_MOD_COMPLETE_QTY,
                           SUM(CASE WHEN A.WO_SEQ = 1 THEN 0 ELSE A.MOD_OPERATION_QTY END) OVER (PARTITION BY A.ORG_WORK_ORDER_ID) AS TOT_MOD_OPERATION_QTY
                    FROM   (
                            SELECT ORG_WORK_ORDER_ID, WORK_ORDER_ID, START_TIME, END_TIME, OPERATION_QTY, COMPLETE_QTY,
                                   (COMPLETE_QTY % 1) AS MOD_COMPLETE_QTY, ((COMPLETE_QTY % 1) * (OPERATION_QTY / COMPLETE_QTY)) AS MOD_OPERATION_QTY,
                                   COUNT(WORK_ORDER_ID) OVER (PARTITION BY ORG_WORK_ORDER_ID) AS WO_CNT,
                                   DENSE_RANK() OVER (PARTITION BY ORG_WORK_ORDER_ID ORDER BY COMPLETE_QTY DESC,WORK_ORDER_ID) AS WO_SEQ
                            FROM   TH_BUF_OUT_WORK_ORDER_SPL
                            WHERE  MASTER_ID      = @v_master_id 
                            AND    PLAN_ID        = @v_plan_id 
                            AND    OUT_VERSION_ID = @v_out_version_id
                            ) A
                    WHERE  WO_CNT > 1
                   ) A
            ;

      DECLARE 							-- 커서로 받을 변수
        @ORG_WORK_ORDER_ID  nvarchar(150),
        @WORK_ORDER_ID      nvarchar(150),
        @CNT                int,
        @TOT_COMPLETE_QTY   numeric(20,10),
        @TOT_OPERATION_QTY  numeric(20,10),
        @MOD_COMPLETE_QTY   numeric(20,10),
        @MOD_OPERATION_QTY  numeric(20,10)

          OPEN C_OUT_ADJ
          
          WHILE 1 = 1
          BEGIN
            
            FETCH C_OUT_ADJ
            INTO  @ORG_WORK_ORDER_ID, @WORK_ORDER_ID, @CNT, @TOT_COMPLETE_QTY, @TOT_OPERATION_QTY, @MOD_COMPLETE_QTY, @MOD_OPERATION_QTY
        
            IF @@FETCH_STATUS <> 0					-- FETCH 레코드 없으면 LOOP 탈출
              BREAK
              
            UPDATE TH_BUF_OUT_WORK_ORDER_SPL
            SET    OPERATION_QTY = OPERATION_QTY + ( CASE WHEN @CNT = 1 THEN @TOT_OPERATION_QTY ELSE @MOD_OPERATION_QTY * (-1) END )
                 , COMPLETE_QTY  = COMPLETE_QTY  + ( CASE WHEN @CNT = 1 THEN @TOT_COMPLETE_QTY  ELSE @MOD_COMPLETE_QTY  * (-1) END )
            WHERE  MASTER_ID      = @v_master_id 
            AND    PLAN_ID        = @v_plan_id 
            AND    OUT_VERSION_ID = @v_out_version_id
            AND    WORK_ORDER_ID  = @WORK_ORDER_ID

          END
          CLOSE C_OUT_ADJ	
          
          DEALLOCATE C_OUT_ADJ
          
        END
        
        -----------------------------------------------------------------------------------------------------------------------------------
        -- TOTAL_WORKING_TIME = 0 인 데이터에 대해 수량 보정
        -----------------------------------------------------------------------------------------------------------------------------------
        BEGIN
        
          DECLARE 
            @TWT_SEQ              Integer,
            @TWT_WO               nvarchar(150),
            @TWT_ORG_WO           nvarchar(150),
            @TWT_OPERATION_QTY    numeric(20,10),
            @TWT_COMPLETE_QTY     numeric(20,10),
            @TWT_ADJ_WO           nvarchar(150),
            @TWT_ADJ_START_TIME   datetime,
            @TWT_ADJ_END_TIME     datetime

          -- 1 STEP : 첫번째 오더가 0 인 경우 그 다음 오더에 수량을 넣어준다. ( START 시간을 변경한다 )
          -- 없을때 까지 무한 LOOP 를 돈다.
          BEGIN
          
            WHILE 1=1
            BEGIN
            
              SET @TWT_WO = 'NULL'
              
              SELECT TOP 1
                     @TWT_WO              = A.WORK_ORDER_ID
                   , @TWT_OPERATION_QTY   = A.OPERATION_QTY
                   , @TWT_COMPLETE_QTY    = A.COMPLETE_QTY
                   , @TWT_ORG_WO          = A.ORG_WORK_ORDER_ID
                   , @TWT_ADJ_WO          = A.NEXT_WORK_ORDER_ID
                   , @TWT_ADJ_START_TIME  = A.NEXT_START_TIME
              FROM   (
                      SELECT A.WORK_ORDER_ID, A.ORG_WORK_ORDER_ID, A.OPERATION_TIME, A.TOTAL_WORKING_TIME, A.OPERATION_QTY, A.COMPLETE_QTY
                           , DENSE_RANK() OVER (PARTITION BY A.ORG_WORK_ORDER_ID ORDER BY A.START_TIME) AS SEQ
                           , LEAD(WORK_ORDER_ID, 1, NULL) OVER (PARTITION BY A.ORG_WORK_ORDER_ID ORDER BY A.START_TIME) AS NEXT_WORK_ORDER_ID
                           , LEAD(START_TIME   , 1, NULL) OVER (PARTITION BY A.ORG_WORK_ORDER_ID ORDER BY A.START_TIME) AS NEXT_START_TIME
                      FROM   TH_BUF_OUT_WORK_ORDER_SPL A,
                             (
                              SELECT MASTER_ID, PLAN_ID, ORG_WORK_ORDER_ID
                              FROM   TH_BUF_OUT_WORK_ORDER_SPL
                              WHERE  MASTER_ID      = @v_master_id
                              AND    PLAN_ID        = @v_plan_id
                              AND    OUT_VERSION_ID = @v_out_version_id
                              AND    COMPLETE_QTY   > 0
                              GROUP  BY MASTER_ID, PLAN_ID, ORG_WORK_ORDER_ID
                              HAVING COUNT(1)                 > 1
                              AND    SUM(TOTAL_WORKING_TIME)  > 0
                              AND    MIN(TOTAL_WORKING_TIME)  = 0
                             ) B
                      WHERE  A.MASTER_ID      = @v_master_id
                      AND    A.PLAN_ID        = @v_plan_id
                      AND    A.OUT_VERSION_ID = @v_out_version_id
                      AND    A.ORG_WORK_ORDER_ID = B.ORG_WORK_ORDER_ID
                      AND    A.COMPLETE_QTY   > 0
                     ) A
              WHERE   A.TOTAL_WORKING_TIME = 0 AND SEQ = 1
              
              IF @TWT_WO = 'NULL'					-- 없으면 LOOP 탈출
                BREAK
                
              UPDATE TH_BUF_OUT_WORK_ORDER_SPL
              SET    OPERATION_QTY  = OPERATION_QTY + @TWT_OPERATION_QTY
                   , COMPLETE_QTY   = COMPLETE_QTY  + @TWT_COMPLETE_QTY
              WHERE  MASTER_ID      = @v_master_id
              AND    PLAN_ID        = @v_plan_id
              AND    OUT_VERSION_ID = @v_out_version_id
              AND    WORK_ORDER_ID  = @TWT_ADJ_WO
              
              UPDATE TH_BUF_OUT_WORK_ORDER_SPL
              SET    OPERATION_QTY  = OPERATION_QTY - @TWT_OPERATION_QTY
                   , COMPLETE_QTY   = COMPLETE_QTY  - @TWT_COMPLETE_QTY
              WHERE  MASTER_ID      = @v_master_id
              AND    PLAN_ID        = @v_plan_id
              AND    OUT_VERSION_ID = @v_out_version_id
              AND    WORK_ORDER_ID  = @TWT_WO
            
              UPDATE TH_BUF_OUT_WORK_ORDER
              SET    START_TIME     = @TWT_ADJ_START_TIME
              WHERE  MASTER_ID      = @v_master_id
              AND    PLAN_ID        = @v_plan_id
              AND    OUT_VERSION_ID = @v_out_version_id
              AND    WORK_ORDER_ID  = @TWT_ORG_WO

            END

            DELETE FROM TH_BUF_OUT_WORK_ORDER_SPL
            WHERE  MASTER_ID      = @v_master_id
            AND    PLAN_ID        = @v_plan_id
            AND    OUT_VERSION_ID = @v_out_version_id
            AND    OPERATION_QTY  = 0
            
          END

          -- 2 STEP : 오더가 0 인 경우 그 이전 오더에 수량을 넣어준다. ( END 시간을 변경한다 )
          --          맨 마지막 오더가 0 이면 ENDTIME 을 조정한다.
          -- 없을때 까지 무한 LOOP 를 돈다.
          BEGIN
          
            WHILE 1=1
            BEGIN
            
              SET @TWT_WO = 'NULL'
              
              SELECT TOP 1
                     @TWT_WO              = A.WORK_ORDER_ID
                   , @TWT_OPERATION_QTY   = A.OPERATION_QTY
                   , @TWT_COMPLETE_QTY    = A.COMPLETE_QTY
                   , @TWT_ORG_WO          = A.ORG_WORK_ORDER_ID
                   , @TWT_ADJ_WO          = A.PREV_WORK_ORDER_ID
                   , @TWT_ADJ_END_TIME    = A.PREV_END_TIME
                   , @TWT_SEQ             = A.SEQ
              FROM   (
                      SELECT A.WORK_ORDER_ID, A.ORG_WORK_ORDER_ID, A.OPERATION_TIME, A.TOTAL_WORKING_TIME, A.OPERATION_QTY, A.COMPLETE_QTY
                           , DENSE_RANK() OVER (PARTITION BY A.ORG_WORK_ORDER_ID ORDER BY A.START_TIME DESC) AS SEQ
                           , LEAD(WORK_ORDER_ID, 1, NULL) OVER (PARTITION BY A.ORG_WORK_ORDER_ID ORDER BY A.START_TIME DESC) AS PREV_WORK_ORDER_ID
                           , LEAD(END_TIME     , 1, NULL) OVER (PARTITION BY A.ORG_WORK_ORDER_ID ORDER BY A.START_TIME DESC) AS PREV_END_TIME
                      FROM   TH_BUF_OUT_WORK_ORDER_SPL A,
                             (
                              SELECT MASTER_ID, PLAN_ID, ORG_WORK_ORDER_ID
                              FROM   TH_BUF_OUT_WORK_ORDER_SPL
                              WHERE  MASTER_ID      = @v_master_id
                              AND    PLAN_ID        = @v_plan_id
                              AND    OUT_VERSION_ID = @v_out_version_id
                              AND    COMPLETE_QTY   > 0
                              GROUP  BY MASTER_ID, PLAN_ID, ORG_WORK_ORDER_ID
                              HAVING COUNT(1)                 > 1
                              AND    SUM(TOTAL_WORKING_TIME)  > 0
                              AND    MIN(TOTAL_WORKING_TIME)  = 0
                             ) B
                      WHERE  A.MASTER_ID      = @v_master_id
                      AND    A.PLAN_ID        = @v_plan_id
                      AND    A.OUT_VERSION_ID = @v_out_version_id
                      AND    A.ORG_WORK_ORDER_ID = B.ORG_WORK_ORDER_ID
                      AND    A.COMPLETE_QTY   > 0
                     ) A
              WHERE   A.TOTAL_WORKING_TIME = 0
              
              IF @TWT_WO = 'NULL'					-- 없으면 LOOP 탈출
                BREAK
                
              UPDATE TH_BUF_OUT_WORK_ORDER_SPL
              SET    OPERATION_QTY  = OPERATION_QTY + @TWT_OPERATION_QTY
                   , COMPLETE_QTY   = COMPLETE_QTY  + @TWT_COMPLETE_QTY
              WHERE  MASTER_ID      = @v_master_id
              AND    PLAN_ID        = @v_plan_id
              AND    OUT_VERSION_ID = @v_out_version_id
              AND    WORK_ORDER_ID  = @TWT_ADJ_WO
              
              UPDATE TH_BUF_OUT_WORK_ORDER_SPL
              SET    OPERATION_QTY  = OPERATION_QTY - @TWT_OPERATION_QTY
                   , COMPLETE_QTY   = COMPLETE_QTY  - @TWT_COMPLETE_QTY
              WHERE  MASTER_ID      = @v_master_id
              AND    PLAN_ID        = @v_plan_id
              AND    OUT_VERSION_ID = @v_out_version_id
              AND    WORK_ORDER_ID  = @TWT_WO
            
              IF @TWT_SEQ = 1
                UPDATE TH_BUF_OUT_WORK_ORDER
                SET    END_TIME       = @TWT_ADJ_END_TIME
                WHERE  MASTER_ID      = @v_master_id
                AND    PLAN_ID        = @v_plan_id
                AND    OUT_VERSION_ID = @v_out_version_id
                AND    WORK_ORDER_ID  = @TWT_ORG_WO

            END

            DELETE FROM TH_BUF_OUT_WORK_ORDER_SPL
            WHERE  MASTER_ID      = @v_master_id
            AND    PLAN_ID        = @v_plan_id
            AND    OUT_VERSION_ID = @v_out_version_id
            AND    OPERATION_QTY  = 0
            
          END
        
        END
        
        -----------------------------------------------------------------------------------------------------------------------------------
        -- 정수화 처리
        -----------------------------------------------------------------------------------------------------------------------------------

        IF CHARINDEX('PACK', @v_master_id) > 0
          BEGIN
          
            UPDATE TH_BUF_OUT_WORK_ORDER_SPL
            SET    COMPLETE_QTY   = FLOOR(COMPLETE_QTY)
                 , OPERATION_QTY  = FLOOR(OPERATION_QTY)
            WHERE  MASTER_ID      = @v_master_id 
            AND    PLAN_ID        = @v_plan_id 
            AND    OUT_VERSION_ID = @v_out_version_id
            
          END
        ELSE
          BEGIN
        
            UPDATE TH_BUF_OUT_WORK_ORDER_SPL
            SET    COMPLETE_QTY   = CEILING(COMPLETE_QTY)
                 , OPERATION_QTY  = CEILING(OPERATION_QTY)
            WHERE  MASTER_ID      = @v_master_id 
            AND    PLAN_ID        = @v_plan_id 
            AND    OUT_VERSION_ID = @v_out_version_id
      
          END

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_WORK_ORDER_SPL', 'UPDATE', @n_log_count, null, @v_message, null
      
        UPDATE TH_BUF_OUT_WORK_ORDER
        SET    TH_BUF_OUT_WORK_ORDER.COMPLETE_QTY   = B.COMPLETE_QTY
             , TH_BUF_OUT_WORK_ORDER.OPERATION_QTY  = B.OPERATION_QTY
        FROM   TH_BUF_OUT_WORK_ORDER A,
               (
                SELECT ORG_WORK_ORDER_ID, 
                       SUM(COMPLETE_QTY) AS COMPLETE_QTY,
                       SUM(OPERATION_QTY) AS OPERATION_QTY
                FROM   TH_BUF_OUT_WORK_ORDER_SPL A
                WHERE  A.MASTER_ID      = @v_master_id 
                AND    A.PLAN_ID        = @v_plan_id 
                AND    A.OUT_VERSION_ID = @v_out_version_id
                GROUP  BY ORG_WORK_ORDER_ID
               ) B
        WHERE  A.MASTER_ID      = @v_master_id 
        AND    A.PLAN_ID        = @v_plan_id 
        AND    A.OUT_VERSION_ID = @v_out_version_id
        AND    A.WORK_ORDER_ID  = B.ORG_WORK_ORDER_ID

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_WORK_ORDER', 'UPDATE', @n_log_count, null, @v_message, null
      
      END

      -----------------------------------------------------------------------------------------------------------------------------------
      -- WORK_ORDER_SPL 의 TOTAL_WORKING_TIME 뻥튀기 현상으로 재조정함
      -----------------------------------------------------------------------------------------------------------------------------------
      BEGIN

        UPDATE TH_BUF_OUT_WORK_ORDER_SPL
        SET    TH_BUF_OUT_WORK_ORDER_SPL.TOTAL_WORKING_TIME = B.COM_WORKING_TIME
        FROM   TH_BUF_OUT_WORK_ORDER_SPL A,
               (
                SELECT *
                FROM   (
                        SELECT A.WORK_ORDER_ID, A.ORG_WORK_ORDER_ID, A.TOTAL_WORKING_TIME AS SPL_WORKING_TIME
                             , A.OPERATION_QTY
                             , SUM(A.TOTAL_WORKING_TIME) OVER (PARTITION BY ORG_WORK_ORDER_ID) AS ORG_WORKING_TIME
                             , B.TOTAL_WORKING_TIME
                             , A.OPERATION_QTY / B.OPERATION_QTY AS RATE
                             , B.TOTAL_WORKING_TIME * (A.OPERATION_QTY / B.OPERATION_QTY) AS COM_WORKING_TIME
                        FROM   TH_BUF_OUT_WORK_ORDER_SPL A,
                               TH_BUF_OUT_WORK_ORDER B
                        WHERE  A.MASTER_ID          = @v_master_id
                        AND    A.PLAN_ID            = @v_plan_id
                        AND    A.OUT_VERSION_ID     = @v_out_version_id
                        AND    A.MASTER_ID          = B.MASTER_ID
                        AND    A.PLAN_ID            = B.PLAN_ID
                        AND    A.OUT_VERSION_ID     = B.OUT_VERSION_ID
                        AND    A.ORG_WORK_ORDER_ID  = B.WORK_ORDER_ID
                        AND    B.OPERATION_QTY      > 0
                       ) A
                WHERE  ORG_WORKING_TIME != TOTAL_WORKING_TIME
               ) B
        WHERE  A.MASTER_ID          = @v_master_id
        AND    A.PLAN_ID            = @v_plan_id
        AND    A.OUT_VERSION_ID     = @v_out_version_id
        AND    A.WORK_ORDER_ID      = B.WORK_ORDER_ID
      
        --LOG 생성
        SET @v_message = 'TOTAL_WORKING_TIME : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_WORK_ORDER_SPL', 'UPDATE', @n_log_count, null, @v_message, null

      END

      -----------------------------------------------------------------------------------------------------------------------------------
      -- BOM EFF_START_DATE ROUTE 모델링 처리
      -----------------------------------------------------------------------------------------------------------------------------------
      BEGIN
      
        UPDATE TH_BUF_OUT_DELIVERY_ORDER
        SET    FROM_ROUTE_ID = CASE WHEN CHARINDEX('^^', FROM_ROUTE_ID) = 0 THEN FROM_ROUTE_ID
                                    ELSE SUBSTRING(FROM_ROUTE_ID, 1, CHARINDEX('^^', FROM_ROUTE_ID)-1)
                               END
             , TO_ROUTE_ID =   CASE WHEN CHARINDEX('^^', TO_ROUTE_ID) = 0 THEN TO_ROUTE_ID
                                    ELSE SUBSTRING(TO_ROUTE_ID, 1, CHARINDEX('^^', TO_ROUTE_ID)-1)
                               END
        WHERE  MASTER_ID      = @v_master_id 
        AND    PLAN_ID        = @v_plan_id 
        AND    OUT_VERSION_ID = @v_out_version_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_DELIVERY_ORDER', 'UPDATE', @n_log_count, null, @v_message, null

        UPDATE TH_BUF_OUT_ORDER_TRACKING
        SET    FROM_ROUTE_ID = CASE WHEN CHARINDEX('^^', FROM_ROUTE_ID) = 0 THEN FROM_ROUTE_ID
                                    ELSE SUBSTRING(FROM_ROUTE_ID, 1, CHARINDEX('^^', FROM_ROUTE_ID)-1)
                               END
             , TO_ROUTE_ID =   CASE WHEN CHARINDEX('^^', TO_ROUTE_ID) = 0 THEN TO_ROUTE_ID
                                    ELSE SUBSTRING(TO_ROUTE_ID, 1, CHARINDEX('^^', TO_ROUTE_ID)-1)
                               END
             , ROUTE_ID    =   CASE WHEN CHARINDEX('^^', ROUTE_ID) = 0 THEN ROUTE_ID
                                    ELSE SUBSTRING(ROUTE_ID, 1, CHARINDEX('^^', ROUTE_ID)-1)
                               END
        WHERE  MASTER_ID      = @v_master_id 
        AND    PLAN_ID        = @v_plan_id 
        AND    OUT_VERSION_ID = @v_out_version_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_ORDER_TRACKING', 'UPDATE', @n_log_count, null, @v_message, null

        UPDATE TH_BUF_OUT_ORDER_TRACKING_DETAIL
        SET    FROM_ROUTE_ID = CASE WHEN CHARINDEX('^^', FROM_ROUTE_ID) = 0 THEN FROM_ROUTE_ID
                                    ELSE SUBSTRING(FROM_ROUTE_ID, 1, CHARINDEX('^^', FROM_ROUTE_ID)-1)
                               END
             , TO_ROUTE_ID =   CASE WHEN CHARINDEX('^^', TO_ROUTE_ID) = 0 THEN TO_ROUTE_ID
                                    ELSE SUBSTRING(TO_ROUTE_ID, 1, CHARINDEX('^^', TO_ROUTE_ID)-1)
                               END
             , ROUTE_ID    =   CASE WHEN CHARINDEX('^^', ROUTE_ID) = 0 THEN ROUTE_ID
                                    ELSE SUBSTRING(ROUTE_ID, 1, CHARINDEX('^^', ROUTE_ID)-1)
                               END
        WHERE  MASTER_ID      = @v_master_id 
        AND    PLAN_ID        = @v_plan_id 
        AND    OUT_VERSION_ID = @v_out_version_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_ORDER_TRACKING_DETAIL', 'UPDATE', @n_log_count, null, @v_message, null

        
        UPDATE TH_BUF_OUT_RESOURCE_USAGE
        SET    ROUTE_ID    =   CASE WHEN CHARINDEX('^^', ROUTE_ID) = 0 THEN ROUTE_ID
                                    ELSE SUBSTRING(ROUTE_ID, 1, CHARINDEX('^^', ROUTE_ID)-1)
                               END
        WHERE  MASTER_ID      = @v_master_id 
        AND    PLAN_ID        = @v_plan_id 
        AND    OUT_VERSION_ID = @v_out_version_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_RESOURCE_USAGE', 'UPDATE', @n_log_count, null, @v_message, null

        UPDATE TH_BUF_OUT_WORK_ORDER
        SET    ROUTE_ID    =   CASE WHEN CHARINDEX('^^', ROUTE_ID) = 0 THEN ROUTE_ID
                                    ELSE SUBSTRING(ROUTE_ID, 1, CHARINDEX('^^', ROUTE_ID)-1)
                               END
        WHERE  MASTER_ID      = @v_master_id 
        AND    PLAN_ID        = @v_plan_id 
        AND    OUT_VERSION_ID = @v_out_version_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_WORK_ORDER', 'UPDATE', @n_log_count, null, @v_message, null

        UPDATE TH_BUF_OUT_WORK_ORDER_SPL
        SET    ROUTE_ID    =   CASE WHEN CHARINDEX('^^', ROUTE_ID) = 0 THEN ROUTE_ID
                                    ELSE SUBSTRING(ROUTE_ID, 1, CHARINDEX('^^', ROUTE_ID)-1)
                               END
        WHERE  MASTER_ID      = @v_master_id 
        AND    PLAN_ID        = @v_plan_id 
        AND    OUT_VERSION_ID = @v_out_version_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_WORK_ORDER_SPL', 'UPDATE', @n_log_count, null, @v_message, null

      END
      

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, null, 'END', 999999, null, '=============== End of procedure ===============', null
    END TRY

    BEGIN CATCH
      BEGIN

        DECLARE 
          @v_error_message nvarchar(max),
          @v_error_procedure nvarchar(max),
          @v_error_line nvarchar(max)

        SET @v_error_message = ERROR_MESSAGE()

        SET @v_error_procedure = ERROR_PROCEDURE()

        SET @v_error_line = convert(nvarchar,ERROR_LINE())


        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_error_procedure, null, 'ERROR', null, @v_error_line, null, @v_error_message

        IF @@TRANCOUNT > 0
           COMMIT WORK 
      END
    END CATCH
END
